/**
 * Resolves the optimal URL for a Payload Media upload object.
 *
 * 1. Prioritizes edited / cropped image sizes (card or thumbnail) generated by Payload's image editor.
 * 2. Adds cache-busting query parameter based on `updatedAt` so browsers & CDNs never display
 *    stale cached original images after an edit or re-upload.
 * 3. Safely handles string URLs, relative paths, and full CDN URLs.
 */
export function getMediaUrl(
  media: any,
  preferredSize: 'card' | 'thumbnail' | 'hero' | 'auto' = 'auto',
): string | null {
  if (!media) return null

  // If a raw string was passed
  if (typeof media === 'string') {
    return media
  }

  if (typeof media !== 'object') return null

  let targetUrl: string | null = null

  // In Payload, when an admin uses the Crop / Frame tool, Payload saves the cropped image
  // directly to media.url. Therefore, media.url is the definitive cropped master file!
  // Fall back to media.sizes only if media.url is missing, or if preferredSize is explicitly requested.
  if (media.url) {
    targetUrl = media.url
  } else if (media.sizes && typeof media.sizes === 'object') {
    if (preferredSize === 'card' && media.sizes.card?.url) {
      targetUrl = media.sizes.card.url
    } else if (preferredSize === 'thumbnail' && media.sizes.thumbnail?.url) {
      targetUrl = media.sizes.thumbnail.url
    } else if (preferredSize === 'hero' && media.sizes.hero?.url) {
      targetUrl = media.sizes.hero.url
    } else {
      targetUrl =
        media.sizes.card?.url ||
        media.sizes.thumbnail?.url ||
        media.sizes.hero?.url ||
        null
    }
  }

  if (!targetUrl) return null

  // Cache-busting: append updatedAt timestamp so client browsers & CDN caches
  // instantly reflect image edits/crops without showing the stale original pic
  const timestamp = media.updatedAt ? new Date(media.updatedAt).getTime() : null
  if (timestamp && !isNaN(timestamp)) {
    const separator = targetUrl.includes('?') ? '&' : '?'
    // Only append if not already containing a v= param
    if (!targetUrl.includes('v=')) {
      targetUrl = `${targetUrl}${separator}v=${timestamp}`
    }
  }

  return targetUrl
}

/**
 * Normalizes focal point coordinates from Payload upload objects.
 * Uses a safe default headroom (14%) to prevent cutting off foreheads and hair.
 */
export function getFocalPoint(
  media: any,
  fallback = { x: '50%', y: '14%' },
): { x: string; y: string } {
  if (!media || typeof media !== 'object') return fallback

  const formatCoord = (val: any, defaultVal: string) => {
    if (val == null || val === '') return defaultVal
    const num = Number(val)
    if (isNaN(num)) return defaultVal
    if (num > 0 && num <= 1) return `${Math.round(num * 100)}%`
    return `${Math.round(num)}%`
  }

  return {
    x: formatCoord(media.focalX, fallback.x),
    y: formatCoord(media.focalY, fallback.y),
  }
}

